/**
 * 媒体生成相关常量定义
 */

/**
 * 图片操作类型
 * image: 图片
 * enlarge: 放大
 * edit: 编辑
 * to_video: 转视频
 */
export const IMAGE_OPERATIONS = {
    GENERATE: 'generate_image',
    ENHANCE: 'enhance',
    EDIT: 'edit',
    ENLARGE: 'enlarge',
    TO_VIDEO: 'to_video',
    DOWNLOAD: 'download_image'
} as const;


/**
 * 视频操作类型
 * video: 视频
 * soundtrack: 配乐
 * frameFilling: 帧填充
 * upscale: 增强
 * changeVideoStyle: 改变视频风格
 */
export const VIDEO_OPERATIONS = {
    UPSCALE: 'upscale',
    GENERATE: 'generate_video',
    SOUNDTRACK: 'soundtrack',
    FRAME_FILLING: 'frame_filling',
    VIDEO_STYLE: 'video_style',
    DOWNLOAD: 'download_video'
} as const;


// 操作类型value数组
export const IMAGE_OPERATION_TYPES = Object.values(IMAGE_OPERATIONS);
export const VIDEO_OPERATION_TYPES = Object.values(VIDEO_OPERATIONS);
export const ALL_OPERATION_TYPES = [...IMAGE_OPERATION_TYPES, ...VIDEO_OPERATION_TYPES];

// 媒体类型常量
export const MEDIA_TYPES = {
    IMAGE: 'image',
    VIDEO: 'video'
} as const;

/**
 * 操作类型分类映射 - 动态生成
 * 根据 IMAGE_OPERATIONS 和 VIDEO_OPERATIONS 自动创建操作类型到媒体类型的映射
 */
export const OPERATION_TYPE_CATEGORIES = {
    // 自动生成图片操作类型映射
    ...Object.values(IMAGE_OPERATIONS).reduce((acc, operationType) => {
        acc[operationType] = MEDIA_TYPES.IMAGE;
        return acc;
    }, {} as Record<string, string>),

    // 自动生成视频操作类型映射
    ...Object.values(VIDEO_OPERATIONS).reduce((acc, operationType) => {
        acc[operationType] = MEDIA_TYPES.VIDEO;
        return acc;
    }, {} as Record<string, string>)
} as const;

// 组件状态常量
export const RESULT_STATES = {
    EMPTY: 'empty',
    LOADING: 'loading',
    SUCCESS: 'success',
    ERROR: 'error'
} as const;

// 工具函数
export const isImageOperation = (operationType: string): boolean => {
    return IMAGE_OPERATION_TYPES.includes(operationType as any);
};

export const isVideoOperation = (operationType: string): boolean => {
    return VIDEO_OPERATION_TYPES.includes(operationType as any);
};

export const getMediaTypeByOperation = (operationType: string): 'image' | 'video' | null => {
    if (isImageOperation(operationType)) {
        return MEDIA_TYPES.IMAGE;
    }
    if (isVideoOperation(operationType)) {
        return MEDIA_TYPES.VIDEO;
    }
    return null;
}; 