import { defineStore } from 'pinia';
import { reactive } from 'vue';
import { IMAGE_OPERATIONS, VIDEO_OPERATIONS } from '../../types/media-tool';

export const useMediaGenerationStore = defineStore('mediaGeneration', () => {
  // 默认视频和封面URL
  const defaultVideoUrl = 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4';
  const defaultPosterUrl = '';

  // 存储各模块生成接口返回的值
  const generationResults = reactive<Record<string, any>>({
    // 图片相关模块
    [IMAGE_OPERATIONS.GENERATE]: {
      imageUrl: defaultPosterUrl,
    },
    [IMAGE_OPERATIONS.ENHANCE]: {
      imageUrl: defaultPosterUrl,
    },
    [IMAGE_OPERATIONS.ENLARGE]: {
      imageUrl: defaultPosterUrl,
    },
    [IMAGE_OPERATIONS.TO_VIDEO]: {
      imageUrl: defaultPosterUrl,
    },
    
    // 视频相关模块
    [VIDEO_OPERATIONS.UPSCALE]: {
      videoUrl: defaultVideoUrl,
      posterUrl: defaultPosterUrl
    },
    [VIDEO_OPERATIONS.SOUNDTRACK]: {
      videoUrl: defaultVideoUrl,
      posterUrl: defaultPosterUrl
    },
    [VIDEO_OPERATIONS.VIDEO_STYLE]: {
      videoUrl: defaultVideoUrl,
      posterUrl: defaultPosterUrl
    },
    [VIDEO_OPERATIONS.FRAME_FILLING]: {
      videoUrl: defaultVideoUrl,
      posterUrl: defaultPosterUrl
    },
    
    // 文本生成模块
    textToImage: null,
    textToVideo: null,
  });

  // 获取指定模块的生成结果
  const getGenerationResult = (moduleKey: string) => {
    return generationResults[moduleKey] || null;
  };

  // 设置指定模块的生成结果
  const setGenerationResult = (moduleKey: string, result: any) => {
    generationResults[moduleKey] = result;
  };

  // 清除指定模块的生成结果
  const clearGenerationResult = (moduleKey: string) => {
    generationResults[moduleKey] = null;
  };

  return {
    generationResults,
    getGenerationResult,
    setGenerationResult,
    clearGenerationResult
  };
}, {}); 